  const unmarkedNotes = [release("v0.2.0"), release("v0.1.5"), release("v0.1.0")];
  const markedNotes = [release("v0.2.0"), release("v0.1.5", `\`${ADOPT_MARKER}\` — take this one`), release("v0.1.0")];

  const notices = (calls: string[][]) => calls.filter((call) => call[0] === "issue" && (call[1] === "create" || call[1] === "edit"));
